{
  "selections": [
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0"],
      "relevance": "상담사가 '계획을 세운 뒤 어떤 순간에 지키지 못하게 되는가'를 질문함. 이 대처 전략은 과제·공부를 시작하려다 답답함이 올라오는 바로 그 순간에 유튜브·SNS를 켜는 패턴을 설명하며, 상황 사례 0에서 저녁 8시에 책상에 앉았다가 개요를 쓰다 막히자 새벽 3시까지 유튜브를 본 장면과 직접 연결됨."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/0"],
      "relevance": "'내일 아침 일찍 일어나서 하면 된다'며 미루고 새 계획표로 죄책감을 달래는 패턴이, 상담사의 '계획을 세우는데 지키지 못하는 순간'이라는 질문에 대한 또 다른 회피 순간을 설명함. 상황 사례 0에서 두 시간 만에 짜깁기 제출 후 '다음 과제는 일주일 전에 시작한다'는 새 계획표를 만든 것과 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "'하기 싫어지면 미루거나 더 재미있는 것으로 넘어가야 한다'는 규칙이, 계획 세운 뒤 답답함이 올라오는 순간에 지키지 못하게 만드는 내적 논리를 설명함. 상담사의 질문에 대한 내담자의 자동적 판단 근거가 됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/0"],
      "relevance": "'지금 불편한 기분을 달래면 나중에 컨디션이 좋아졌을 때 몰아서 해낼 수 있다'는 기대가, 유튜브를 켜는 순간의 합리화 논리이며 상담사가 묻는 '지키지 못하게 되는 순간'의 인지적 근거를 제공함."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "'지루하고 답답한 것을 억지로 참고 하는 것은 불가능에 가까운 고통'이라는 태도가, 계획 세운 뒤 불편함이 올라오는 순간에 회피를 선택하게 만드는 기저 신념이며 성장 배경에서 '불편함은 피하면 된다'는 규칙이 몸에 밴 것과 연결됨."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 반복되는 '계획 세우기-지키지 못하기' 패턴을 질문하고 있어, 부족한 자기통제/자기훈련 스키마가 이 대화의 중심 주제와 직접 관련됨. 성장 배경에서 하기 싫은 것을 참고 끝까지 해본 경험이 쌓이지 못한 것이 이 스키마의 발생 맥락임."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/3"],
      "relevance": "'나는 하기 싫고 답답한 일을 스스로 하게 만들 수 없는 사람이다'라는 핵심 신념이, 상담사의 질문에 내담자가 답할 때 드러날 자기 인식과 연결됨. 상황 사례 3에서 '지금까지 몇 번을 그렇게 결심했더라. 나는 결심을 지켜본 적이 없는데 이번이라고 될까'라는 생각이 이 신념의 발현임."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/3"],
      "relevance": "자기관리 장치를 의욕적으로 시작하지만 2주를 넘기지 못하는 패턴이, '계획은 잘 세우는데 한 번도 지켜본 적이 없다'는 내담자의 호소와 상담사의 질문에 대한 보편적 답변 근거가 됨. 상황 사례 3에서 도서관 좌석을 등록하고 첫날 두 시간 만에 나온 것과 연결됨."
    }
  ]
}

